cpp.setup:
auto* control = new fluent::layout::DataGridToolBar(%PARENT%);
auto* model = new QStandardItemModel(2, 3, control);
model->setHorizontalHeaderLabels({QStringLiteral("Project"), QStringLiteral("Owner"), QStringLiteral("Status")});
model->setItem(0, 0, new QStandardItem(QStringLiteral("FluentQt")));
model->setItem(0, 1, new QStandardItem(QStringLiteral("Ada")));
model->setItem(0, 2, new QStandardItem(QStringLiteral("Open")));
model->setItem(1, 0, new QStandardItem(QStringLiteral("Gallery")));
model->setItem(1, 1, new QStandardItem(QStringLiteral("Lin")));
model->setItem(1, 2, new QStandardItem(QStringLiteral("Closed")));
auto* grid = new fluent::collections::DataGrid(control);
grid->setModel(model);
grid->hide();
control->setDataGrid(grid);
control->searchField()->setPlaceholderText(QStringLiteral("Search projects..."));
control->addFilter(QStringLiteral("status"), QStringLiteral("Status"), {QStringLiteral("Open"), QStringLiteral("Closed")});
